<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
date_default_timezone_set('America/Lima');
function announcement_local_time(?string $value): ?string {if(!$value)return null;return (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Lima'))->format('Y-m-d H:i:s');}
$user=require_permission('announcements','view');$db=admin_db();$error='';$uploadedPath='';$uploadCreation='';$announcementSaved=false;
try{
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'');
        if($action==='save'){
            $id=(int)($_POST['id']??0);require_permission('announcements',$id?'edit':'create');$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Escribe un nombre interno para el anuncio.');
            $previous='';if($id){$q=$db->prepare('SELECT image_path FROM home_announcements WHERE id=?');$q->execute([$id]);$previous=(string)($q->fetchColumn()?:'');}
            if(!empty($_FILES['image']['name']))$uploadedPath=save_upload($db,$_FILES['image'],(int)$user['id'],$uploadCreation);$image=$uploadedPath?:$previous;if($image==='')throw new RuntimeException('Selecciona una imagen para el anuncio.');
            $permanent=isset($_POST['is_permanent']);$expires=null;if(!$permanent){$raw=trim((string)($_POST['expires_at']??''));if($raw==='')throw new RuntimeException('Indica la fecha y hora de vencimiento.');$date=date_create_immutable($raw,new DateTimeZone('America/Lima'));if(!$date)throw new RuntimeException('La fecha de vencimiento no es válida.');$expires=$date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
            $values=[$name,$image,trim((string)($_POST['alt_es']??'')),trim((string)($_POST['alt_en']??'')),$permanent?1:0,$expires,isset($_POST['is_active'])?1:0,(int)($_POST['sort_order']??0)];
            if($id){$values[]=$id;$db->prepare('UPDATE home_announcements SET name=?,image_path=?,alt_es=?,alt_en=?,is_permanent=?,expires_at=?,is_active=?,sort_order=? WHERE id=?')->execute($values);}else{$db->prepare('INSERT INTO home_announcements(name,image_path,alt_es,alt_en,is_permanent,expires_at,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?)')->execute($values);$id=(int)$db->lastInsertId();}
            $announcementSaved=true;$cleanup=release_replaced_media($db,[$previous],[$image],(int)$user['id'],'home-announcement',$id);if($cleanup['errors'])audit($db,(int)$user['id'],'cleanup-failed','media',$id,$cleanup);audit($db,(int)$user['id'],'save','home-announcement',$id);mark_public_content_changed('announcements');flash('success','Anuncio guardado y actualizado en la web.');header('Location: /admin/announcements.php');exit;
        }
        if($action==='delete'){
            require_permission('announcements','delete');$id=(int)($_POST['id']??0);$q=$db->prepare('SELECT image_path FROM home_announcements WHERE id=?');$q->execute([$id]);$path=(string)($q->fetchColumn()?:'');$db->prepare('DELETE FROM home_announcements WHERE id=?')->execute([$id]);$cleanup=release_replaced_media($db,[$path],[],(int)$user['id'],'home-announcement',$id);if($cleanup['errors'])audit($db,(int)$user['id'],'cleanup-failed','media',$id,$cleanup);audit($db,(int)$user['id'],'delete','home-announcement',$id);mark_public_content_changed('announcements');flash('success','Anuncio eliminado y actualizado en la web.');header('Location: /admin/announcements.php');exit;
        }
    }
}catch(Throwable $exception){if(!$announcementSaved&&$uploadedPath!==''&&$uploadCreation!=='')cleanup_failed_uploads($db,[['path'=>$uploadedPath,'creation'=>$uploadCreation]]);$error=$exception->getMessage();}
$edit=null;$editId=(int)($_GET['edit']??0);if($editId){$q=$db->prepare('SELECT * FROM home_announcements WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;if($edit)$edit['expires_at']=announcement_local_time($edit['expires_at']);}
$items=$db->query('SELECT * FROM home_announcements ORDER BY sort_order,id')->fetchAll();foreach($items as &$announcementItem)$announcementItem['expires_at']=announcement_local_time($announcementItem['expires_at']);unset($announcementItem);$flash=pull_flash();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Anuncios de inicio | Royal Beans Perú</title><link rel="stylesheet" href="/admin/admin.css"><style>.announcement-layout{display:grid;grid-template-columns:minmax(300px,430px) 1fr;gap:24px}.announcement-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}.announcement-card{overflow:hidden}.announcement-card img{width:100%;aspect-ratio:4/3;object-fit:contain;background:#edf1eb}.announcement-card-body{display:grid;gap:9px;padding:16px}.announcement-card-body p{margin:0;color:#607068}.announcement-actions{display:flex;gap:8px;align-items:center}.announcement-actions form{margin:0}.announcement-status{width:max-content;padding:5px 9px;border-radius:999px;background:#e7f5d8;font-size:11px;font-weight:750}.announcement-status.expired{background:#f5dddd;color:#8b3030}@media(max-width:950px){.announcement-layout{grid-template-columns:1fr}}</style></head><body class="admin-body"><aside class="admin-sidebar"><a class="admin-brand" href="/admin/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>ADMINISTRACIÓN</small></span></a><nav></nav><div class="admin-user"><strong><?=e($user['name'])?></strong><small><?=e($user['role'])?></small><a href="/admin/?view=logout">Cerrar sesión</a></div></aside><main class="admin-main"><header class="admin-top"><div><p class="admin-eyebrow">Inicio</p><h1>Anuncios en imagen</h1><p>Cada anuncio controla su propia vigencia y orden.</p></div></header><?php if($flash):?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="announcement-layout"><form class="admin-panel admin-form" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><h2><?=$edit?'Editar anuncio':'Nuevo anuncio'?></h2><label>Nombre interno<input name="name" maxlength="190" required value="<?=e($edit['name']??'')?>" placeholder="Ej.: Feria de septiembre"></label><label><?=$edit?'Reemplazar imagen':'Imagen del anuncio'?><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/avif" <?=$edit?'':'required'?>></label><?php if($edit):?><img src="<?=e($edit['image_path'])?>" alt="" style="width:100%;max-height:230px;object-fit:contain;background:#edf1eb;border-radius:8px"><?php endif;?><label>Texto alternativo ES<input name="alt_es" maxlength="255" value="<?=e($edit['alt_es']??'')?>"></label><label>Texto alternativo EN<input name="alt_en" maxlength="255" value="<?=e($edit['alt_en']??'')?>"></label><label>Orden<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label><input type="checkbox" name="is_active" value="1" <?=!$edit||$edit['is_active']?'checked':''?>> Anuncio activo</label><label><input id="permanent" type="checkbox" name="is_permanent" value="1" <?=!$edit||$edit['is_permanent']?'checked':''?>> Mostrar de por vida</label><label id="expires-label">Visible hasta<input type="datetime-local" name="expires_at" value="<?=!empty($edit['expires_at'])?e(date('Y-m-d\TH:i',strtotime($edit['expires_at']))):''?>"></label><div class="form-actions"><?php if($edit):?><a class="secondary-button" href="/admin/announcements.php">Cancelar</a><?php endif;?><button class="primary-button">Guardar anuncio</button></div></form><section class="announcement-list"><?php foreach($items as $item):$expired=!$item['is_permanent']&&$item['expires_at']&&strtotime($item['expires_at'])<=time();?><article class="admin-panel announcement-card"><img src="<?=e($item['image_path'])?>" alt=""><div class="announcement-card-body"><span class="announcement-status <?=$expired?'expired':''?>"><?=$item['is_permanent']?'Permanente':($expired?'Vencido':'Hasta '.e(date('d/m/Y H:i',strtotime($item['expires_at']))))?></span><strong><?=e($item['name'])?></strong><p>Orden: <?=e($item['sort_order'])?> · <?=$item['is_active']?'Activo':'Desactivado'?></p><div class="announcement-actions"><a class="secondary-button" href="?edit=<?=$item['id']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este anuncio?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$item['id']?>"><button class="danger-button">Eliminar</button></form></div></div></article><?php endforeach;?><?php if(!$items):?><div class="admin-panel"><p>No hay anuncios todavía.</p></div><?php endif;?></section></div></main><script>const permanent=document.querySelector('#permanent'),expires=document.querySelector('#expires-label');function syncExpiry(){expires.hidden=permanent.checked;expires.querySelector('input').required=!permanent.checked}permanent.addEventListener('change',syncExpiry);syncExpiry();</script></body></html>
